def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            value = f"{local}@{domain}"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return value

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    records = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        records.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "updated": parse_updated(row["updated"]),
            "opted_out": opted_out(row["opted_out"]),
            "tags": [
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            ],
        })

    # Build transitive groups using connected components.
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}

    for i, record in enumerate(records):
        email = record["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        phone, last_name = record["phone"], record["last_name"]
        if phone and last_name:
            key = (phone, last_name.casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(find(i), []).append(record)

    def choose(group, field):
        eligible = [r for r in group if r[field]]
        if not eligible:
            return ""
        winner = min(
            eligible,
            key=lambda r: (
                r["source"] != "manual",
                -r["updated"].timestamp(),
                r["index"],
            ),
        )
        return winner[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(r["index"] for r in g)):
        latest = max(r["updated"] for r in group)
        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted({tag for r in group for tag in r["tags"]})),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
